insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 9, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Why was the Simon Commission greeted with the slogan 'Go back Simon' when it arrived in India in 1928?$paper_seed$, null, null, null, $paper_seed${"model_answer":"The Simon Commission was sent to India in 1928 to look into the functioning of the constitutional system and suggest changes — but it did not include a single Indian member. Nationalists saw this as an insult to Indians' right to shape their own future. When the Commission arrived, it was greeted with black flags and the slogan 'Go back Simon', with the Congress and the Muslim League joining the protests together.","points":[{"point":"The Commission was set up to review the constitutional system, but it did not have a single Indian member","marks":1},{"point":"Indians across parties saw this as an insult to their right to decide their own future, so it was met with protests and black flags","marks":1}]}$paper_seed$::jsonb);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 10, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$What was the Inland Emigration Act of 1859? How did plantation workers in Assam respond to the news of the Non-Cooperation Movement?$paper_seed$, null, null, null, $paper_seed${"model_answer":"Under the Inland Emigration Act of 1859, plantation workers in Assam were not permitted to leave the tea gardens without permission — and permission was hardly ever granted. When news of the Non-Cooperation Movement reached the plantations, thousands of workers defied the authorities, left the gardens and headed home. They believed that Gandhi Raj was coming and that everyone would be given land in their own villages. For them, freedom meant the right to move freely and keep a link with their village.","points":[{"point":"Under the Act, plantation workers were not permitted to leave the tea gardens without permission, which was rarely given","marks":1},{"point":"On hearing of the movement, thousands defied the authorities, left the plantations and headed home, believing Gandhi Raj was coming and everyone would get land in their own villages","marks":1}]}$paper_seed$::jsonb);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 11, $paper_seed$B$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Why did Gandhiji choose salt as the symbol for the Civil Disobedience Movement?$paper_seed$, null, null, null, $paper_seed${"model_answer":"Gandhiji chose salt because it was something consumed by the rich and the poor alike — one of the most essential items of food. The tax on salt, and the government's monopoly over its production, hit every Indian household. In his letter to Viceroy Irwin, Gandhiji declared the salt tax the most oppressive face of British rule, which made salt a powerful symbol that could unite the whole nation.","points":[{"point":"Salt was consumed by the rich and the poor alike, and was one of the most essential items of food","marks":1},{"point":"The tax on salt and the government monopoly over its production revealed the most oppressive face of British rule","marks":1}]}$paper_seed$::jsonb);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 12, $paper_seed$C$paper_seed$, $paper_seed$text$paper_seed$, 3, $paper_seed$Describe the three local satyagraha movements Gandhiji organised after arriving in India, before the Rowlatt Satyagraha of 1919.$paper_seed$, null, null, null, $paper_seed${"model_answer":"After returning to India in 1915, Gandhiji successfully organised three local satyagrahas. In 1917 he travelled to Champaran in Bihar to inspire the peasants to struggle against the oppressive indigo plantation system. In the same year, he organised a satyagraha to support the peasants of Kheda district in Gujarat, who were demanding relaxation of revenue collection because crops had failed and a plague epidemic had struck. Then in 1918, he went to Ahmedabad to organise a satyagraha movement amongst cotton mill workers over wages.","points":[{"point":"Champaran, Bihar (1917): inspired the peasants to struggle against the oppressive indigo plantation system","marks":1},{"point":"Kheda, Gujarat (1917): supported peasants demanding relaxation of revenue collection after crop failure and a plague epidemic","marks":1},{"point":"Ahmedabad (1918): organised a satyagraha amongst cotton mill workers","marks":1}]}$paper_seed$::jsonb);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 13, $paper_seed$C$paper_seed$, $paper_seed$text$paper_seed$, 3, $paper_seed$How did the First World War create a new economic and political situation in India?$paper_seed$, null, null, null, $paper_seed${"model_answer":"The First World War created a new economic and political situation in India. Defence expenditure increased enormously and was financed by war loans and by raising taxes — customs duties went up and income tax was introduced. Prices doubled between 1913 and 1918, causing extreme hardship for common people. Villages were angered by the forced recruitment of soldiers. Then crops failed in 1918-19 and 1920-21, leading to acute food shortages, and an influenza epidemic struck. According to the 1921 census, 12 to 13 million people died as a result of the famines and the epidemic. People hoped their hardships would end after the war — but that did not happen, and anger against colonial rule grew.","points":[{"point":"Defence expenditure rose enormously, financed by war loans and higher taxes: customs duties were raised and income tax introduced","marks":1},{"point":"Prices doubled between 1913 and 1918, causing extreme hardship, while forced recruitment in villages caused widespread anger","marks":1},{"point":"Crops failed in 1918-19 and 1920-21, and an influenza epidemic struck — 12 to 13 million people died of famine and epidemic","marks":1}]}$paper_seed$::jsonb);

insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 14, $paper_seed$D$paper_seed$, $paper_seed$text$paper_seed$, 5, $paper_seed$Explain the course of the Civil Disobedience Movement (1930-34). How was it different from the Non-Cooperation Movement?$paper_seed$, null, null, null, $paper_seed${"model_answer":"The Civil Disobedience Movement began with the famous Salt March. Between 12 March and 6 April 1930, Gandhiji and 78 volunteers walked about 240 miles from his ashram at Sabarmati to the coastal town of Dandi, where he ceremonially violated the salt law by making salt from sea water. The movement spread rapidly: thousands in different parts of the country broke the salt law, foreign cloth was boycotted, liquor shops were picketed, peasants refused to pay revenue, village officials resigned, and in many places forest people violated forest laws. Worried by these developments, the government responded with brutal repression — peaceful satyagrahis were attacked and about 100,000 people were arrested, including Gandhiji himself. The movement was called off after the Gandhi-Irwin Pact of 5 March 1931, under which Gandhiji agreed to attend the Second Round Table Conference in London. When the conference failed, the movement was relaunched, but by 1934 it had lost its momentum. The crucial difference from the Non-Cooperation Movement was that people were now asked not only to refuse cooperation with the British, but to actively break colonial laws — beginning with the salt law.","points":[{"point":"Began with the Salt March: from 12 March to 6 April 1930, Gandhiji walked about 240 miles from Sabarmati to Dandi with 78 volunteers, and broke the salt law by making salt from sea water","marks":1},{"point":"The movement spread: thousands broke the salt law, boycotted foreign cloth, picketed liquor shops; peasants refused to pay revenue and village officials resigned; forest people violated forest laws","marks":1},{"point":"The government responded with brutal repression and mass arrests including Gandhiji himself; the movement was called off after the Gandhi-Irwin Pact of 5 March 1931","marks":1},{"point":"It was relaunched when the Second Round Table Conference failed, but by 1934 it lost momentum","marks":1},{"point":"Difference from Non-Cooperation: people were now asked not only to refuse cooperation with the British, but to actively BREAK colonial laws","marks":1}]}$paper_seed$::jsonb);

