insert into questions (paper_id, position, section_label, qtype, marks, prompt, source_id, options, correct_index, scheme)
values ($paper_seed$c10-hist-ch2-p1$paper_seed$, 17, $paper_seed$E$paper_seed$, $paper_seed$text$paper_seed$, 2, $paper_seed$Explain two reasons why this movement gradually slowed down in the cities.$paper_seed$, $paper_seed$src-towns$paper_seed$, null, null, $paper_seed${"model_answer":"The movement slowed down in the cities for two main reasons. First, khadi cloth was often more expensive than mass-produced mill cloth, and poor people could not afford to buy it — so they could not boycott mill cloth for long. Second, the boycott of British institutions required alternative Indian institutions — schools, colleges and courts — to be set up in their place, and these were slow to come up. As a result, students and teachers began returning to government schools, and lawyers joined back in government courts.","points":[{"point":"Khadi cloth was often more expensive than mass-produced mill cloth, so the poor could not afford to buy it","marks":1},{"point":"Alternative Indian institutions were slow to come up, so students and teachers began trickling back to government schools and lawyers back to the courts","marks":1}]}$paper_seed$::jsonb);

